mapper.select:
select  from nad_payment_document
where payment_id = #{paymentId} and kind = #{kind}
order by version desc limit 1

select  from nad_payment_document
where kind = #{kind} and version = #{version} and delivered_at is null
order by id limit #{limit}

mapper.delete:
delete from nad_payment_document_delivery
where document_id = #{documentId} and recipient_user_id = #{userId} and sent_at is null
  and claimed_at < #{cutoff}
